package text

import (
	"encoding/json"
	"os"
	"slices"
	"testing"

	"golang.org/x/text/collate"
)

// TestCollateOracle is the collation gate for WP4a (#40): before anything
// that sorts with Collate was ported, this checked that golang.org/x/text/
// collate's `en` table (CLDR 23 / Unicode 6.2) agrees with Node 24's ICU
// (CLDR 48 / Unicode 17) on internal/text/testdata/collation-corpus.json,
// generated by tools/oracle/collation-corpus.ts from real `localeCompare(…,
// 'en')` calls. Regenerate with:
//
//	export PATH=$HOME/.local/opt/node-v24.14.1-linux-x64/bin:$PATH
//	node tools/oracle/collation-corpus.ts > internal/text/testdata/collation-corpus.json
//
// The corpus is split in two. `realistic` is everything a Git branch, a
// config's project name, or a domain label plausibly is: ASCII, case pairs,
// punctuation and hyphens against letters, digit runs, Latin-1 and accented
// letters (precomposed and decomposed), and shared prefixes — several
// thousand strings, and Collate must reproduce Node's order and every
// pairwise sign on all of them, exactly. `wide` is CJK, Hangul, Kana, emoji,
// and an exhaustive sweep of every combining diacritical mark: real
// disagreements exist there (see TestCollateWideScriptsDiverge, and the
// divergence ledger), because x/text/collate's tables predate most of it,
// but berth's own fields never carry it, so it does not gate the port.
type collationOracle struct {
	ICU       string          `json:"icu"`
	CLDR      string          `json:"cldr"`
	Unicode   string          `json:"unicode"`
	Realistic collationSubset `json:"realistic"`
	Wide      collationSubset `json:"wide"`
}

type collationSubset struct {
	Input  []string              `json:"input"`
	Sorted []string              `json:"sorted"`
	Pairs  []collationOraclePair `json:"pairs"`
}

type collationOraclePair struct {
	Left  string `json:"left"`
	Right string `json:"right"`
	Sign  int    `json:"sign"`
}

func loadCollationOracle(t *testing.T) collationOracle {
	t.Helper()
	data, err := os.ReadFile("testdata/collation-corpus.json")
	if err != nil {
		t.Fatalf("reading oracle data: %v", err)
	}
	var oracle collationOracle
	if err := json.Unmarshal(data, &oracle); err != nil {
		t.Fatalf("parsing oracle data: %v", err)
	}
	if len(oracle.Realistic.Input) == 0 || len(oracle.Wide.Input) == 0 {
		t.Fatal("empty oracle corpus")
	}
	return oracle
}

// TestCollateOracleRealisticSortOrder sorts the realistic subset with
// Collate — stably, as Node's Array.prototype.sort and Collate's callers
// both rely on — and requires the exact order Node's own localeCompare('en')
// produced. A failure here means x/text/collate cannot stand in for
// localeCompare on the strings berth actually sorts, and the rest of the
// checkout-index renderer must not be ported until that is resolved.
func TestCollateOracleRealisticSortOrder(t *testing.T) {
	oracle := loadCollationOracle(t)
	t.Logf("Node ICU %s / CLDR %s / Unicode %s; golang.org/x/text/collate CLDR %s / Unicode %s",
		oracle.ICU, oracle.CLDR, oracle.Unicode, collate.CLDRVersion, collate.UnicodeVersion)

	got := slices.Clone(oracle.Realistic.Input)
	slices.SortStableFunc(got, Collate)

	if slices.Equal(got, oracle.Realistic.Sorted) {
		return
	}
	mismatches := 0
	for i := range oracle.Realistic.Sorted {
		if i >= len(got) || got[i] != oracle.Realistic.Sorted[i] {
			mismatches++
			if mismatches <= 25 {
				var gotHere string
				if i < len(got) {
					gotHere = got[i]
				}
				t.Errorf("index %d: Collate sorts %q, localeCompare('en') sorts %q", i, gotHere, oracle.Realistic.Sorted[i])
			}
		}
	}
	t.Fatalf("%d of %d realistic positions disagree with Node's localeCompare('en') order", mismatches, len(oracle.Realistic.Sorted))
}

// TestCollateOracleRealisticPairs checks the pairwise sign Node's
// localeCompare('en') gave for every consecutive pair of the realistic
// corpus, plus an all-pairs cross-check over a handful of single-character
// probes, independent of overall sort-order agreement.
func TestCollateOracleRealisticPairs(t *testing.T) {
	oracle := loadCollationOracle(t)
	checkPairs(t, oracle.Realistic.Pairs)
}

// TestCollateWideScriptsDiverge pins the accepted difference: for CJK,
// Hangul, Kana, emoji, and the full sweep of combining diacritical marks,
// x/text/collate's CLDR-23 tables do not always agree with Node's CLDR-48
// ICU. This is divergence 8 in docs/port/divergences.md. The test does not
// require agreement — it requires that the *known* disagreement is what
// still disagrees, so a future x/text/collate update that closes the gap is
// noticed (the mismatch count drops to zero) rather than silently kept.
func TestCollateWideScriptsDiverge(t *testing.T) {
	oracle := loadCollationOracle(t)

	got := slices.Clone(oracle.Wide.Input)
	slices.SortStableFunc(got, Collate)
	sortMismatches := 0
	for i := range oracle.Wide.Sorted {
		if i >= len(got) || got[i] != oracle.Wide.Sorted[i] {
			sortMismatches++
		}
	}
	if sortMismatches == 0 {
		t.Fatal("x/text/collate now reproduces Node's order for CJK/Hangul/Kana/emoji/combining-mark strings; " +
			"promote the wide corpus into the realistic gate and update divergence 8 in docs/port/divergences.md")
	}
	t.Logf("%d of %d wide-script positions disagree with Node's localeCompare('en') order (expected, see divergence 8)",
		sortMismatches, len(oracle.Wide.Sorted))

	pairMismatches := 0
	for _, pair := range oracle.Wide.Pairs {
		if sign(Collate(pair.Left, pair.Right)) != pair.Sign {
			pairMismatches++
		}
	}
	if pairMismatches == 0 {
		t.Fatal("x/text/collate now agrees with Node on every sampled wide-script pair; " +
			"promote the wide corpus into the realistic gate and update divergence 8 in docs/port/divergences.md")
	}
	t.Logf("%d of %d wide-script pairs disagree with Node's localeCompare('en') sign (expected, see divergence 8)",
		pairMismatches, len(oracle.Wide.Pairs))
}

func checkPairs(t *testing.T, pairs []collationOraclePair) {
	t.Helper()
	mismatches := 0
	for _, pair := range pairs {
		got := sign(Collate(pair.Left, pair.Right))
		if got != pair.Sign {
			mismatches++
			if mismatches <= 25 {
				t.Errorf("Collate(%q, %q) sign = %d, localeCompare('en') sign = %d", pair.Left, pair.Right, got, pair.Sign)
			}
		}
	}
	if mismatches > 0 {
		t.Fatalf("%d of %d pairs disagree with Node's localeCompare('en') sign", mismatches, len(pairs))
	}
}

func sign(n int) int {
	switch {
	case n < 0:
		return -1
	case n > 0:
		return 1
	default:
		return 0
	}
}
